from concurrent.futures import ThreadPoolExecutor


def square(x: int) -> int:
    return x * x


def squares(xs: list[int]) -> list[int]:
    """Return [square(x) for x in xs], computing each element in a thread pool.

    The result preserves the order of xs. An empty input returns an empty list.
    """
    with ThreadPoolExecutor() as ex:
        return list(ex.map(square, xs))


def test_square() -> None:
    assert square(3) == 9
    assert square(-4) == 16


def test_squares_basic() -> None:
    assert squares([1, 2, 3]) == [1, 4, 9]


def test_squares_empty() -> None:
    assert squares([]) == []


def test_squares_negatives_and_zero() -> None:
    assert squares([-2, 0, 5]) == [4, 0, 25]


def test_squares_preserves_order() -> None:
    xs = list(range(1000))
    assert squares(xs) == [x * x for x in xs]


def test_squares_returns_new_list() -> None:
    xs = [1, 2]
    out = squares(xs)
    assert out is not xs
    assert xs == [1, 2]
